# Let me map each position with 2 to its replacement value
# and try to find the pattern

rows = 24
cols = 24

# Map positions
pattern_map = {}
for r in range(rows):
    for c in range(cols):
        if input_demo[r][c] == 2:
            pattern_map[(r, c)] = output_demo[r][c]

