for root, dirs, filenames in os.walk(workspace_base):
    for f in filenames:
        if 'd48db2ba' in f.lower():
            files_with_taskid.append(os.path.join(root, f))

print(f"Files with d48db2ba: {files_with_taskid}")

# Pattern 2: Recent files with 'game' in name
game_files = []
for root, dirs, filenames in os.walk(workspace_base):
    for f in filenames:
        if 'stat' in f.lower() and (f.endswith('.json') or f.endswith('.jsonl') or f.endswith('.txt')):
            path = os.path.join(root, f)
