"""
Check the mcp module for available tools
"""
import rlm.mcp as mcp

print("MCP module analysis:")

# Try to discover the mcp catalog services
try:
    catalog = mcp.check_system_catalog()
    print(f"Catalog: {catalog}")
except Exception as e:
    print(f"Cannot check catalog: {e}")

# Check for available mcp tools
try:
    result = mcp.list_tools()
    print(f"\nAvailable tools: {result}")
except Exception as e:
    print(f"\nError listing tools: {e}")

# Try calling mcp() to see what's available
try:
    mcp_list = mcp()
    print(f"\nMCP tools list: {mcp_list}")
except Exception as e:
    print(f"\nError with mcp(): {e}")

# Check for 'run_python' tool
try:
    tools_info = mcp.list_tools()
    for tool in tools_info:
        if 'run' in tool.get('name', '').lower() or 'python' in tool.get('name', '').lower():
            print(f"\nFound Python-related tool: {tool}")
except Exception as e:
    print(f"MCP list_tools error: {e}")

